mod_steps_server <- function(id, params_reactive) {
  shiny::moduleServer(id, function(input, output, session) {
    ns <- session$ns

    # Init: Gewicht aus Metadaten übernehmen
    shiny::observeEvent(params_reactive(), {
      p <- params_reactive(); shiny::req(p)
      w <- p$Weight_kg %||% NA_real_
      if (is.finite(w))
        shiny::updateNumericInput(session, "weight", value = round(w, 1))
    })

    summary_r <- shiny::reactive({
      p <- params_reactive(); shiny::req(p, !is.null(p$ts))
      w <- input$weight
      if (!is.finite(w)) w <- p$Weight_kg %||% NA_real_
      ws <- input$window_sec %||% 30
      ms <- input$min_step %||% 15
      build_step_summary(p$ts,
        weight_kg    = w,
        window_sec   = if (is.finite(ws) && ws > 0) ws else 30,
        min_step_sec = if (is.finite(ms) && ms > 0) ms else 15)
    })

    n_belastung_steps <- shiny::reactive({
      df <- tryCatch(summary_r(), error = function(e) NULL)
      if (is.null(df)) return(0L)
      sum(df$type == "Belastung", na.rm = TRUE)
    })

    mfo_r <- shiny::reactive({
      df <- tryCatch(summary_r(), error = function(e) NULL)
      calc_MFO(df)
    })

    # Status-Hinweis am Toggle (z.B. "nur 2 Stufen vorhanden")
    output$mfo_status_hint <- shiny::renderUI({
      n <- n_belastung_steps()
      if (n < 3) {
        shiny::span(class = "mfo-disabled-hint",
          shiny::icon("circle-info"),
          sprintf(" %d Stufe(n) – ab 3 Stufen sinnvoll.", n))
      } else {
        shiny::span(class = "mfo-disabled-hint",
          shiny::icon("circle-check"),
          sprintf(" %d Belastungs-Stufen erkannt.", n))
      }
    })

    # ── MFO-Karten ────────────────────────────────────────
    output$mfo_cards <- shiny::renderUI({
      mf <- mfo_r()
      mfo_txt <- if (isTRUE(mf$ok))
        sprintf("%.2f g·min⁻¹", mf$MFO) else "–"
      fmax_txt <- if (isTRUE(mf$ok))
        sprintf("%.0f W", mf$Fatmax_W) else "–"
      sub_txt <- if (isTRUE(mf$ok))
        "am Maximum der Polynomfunktion" else "Berechnung nicht möglich"
      shiny::div(class = "mfo-cards",
        shiny::div(class = "mfo-card mfo-orange",
          shiny::tags$i(class = "fa fa-fire mfo-icon"),
          shiny::div(
            shiny::div(class = "mfo-lbl", "MFO"),
            shiny::div(class = "mfo-num", mfo_txt),
            shiny::div(class = "mfo-sub", sub_txt))),
        shiny::div(class = "mfo-card mfo-blue",
          shiny::tags$i(class = "fa fa-bolt mfo-icon"),
          shiny::div(
            shiny::div(class = "mfo-lbl", "Fatmax (Power)"),
            shiny::div(class = "mfo-num", fmax_txt),
            shiny::div(class = "mfo-sub",
              "Belastung mit höchster Fettoxidation"))))
    })

    # Warn-Box bei Problemen
    output$mfo_warning_box <- shiny::renderUI({
      mf <- mfo_r()
      if (isTRUE(mf$ok) || is.null(mf) || is.null(mf$reason)) return(NULL)
      shiny::div(class = "mfo-warning",
        shiny::icon("triangle-exclamation"),
        " ", mf$reason, ".")
    })

    # ── MFO-Plot (Frontiers-Stil) ─────────────────────────
    output$mfo_plot <- plotly::renderPlotly({
      mf <- mfo_r()
      shiny::req(mf, !is.null(mf$x), length(mf$x) >= 1)

      x  <- mf$x; y <- mf$y
      fx <- mf$fit_x; fy <- mf$fit_y

      # Achsen-Bereiche
      x_max <- max(c(x, fx), na.rm = TRUE) * 1.05
      x_min <- 0
      y_max <- max(c(y, fy, mf$MFO), na.rm = TRUE)
      if (!is.finite(y_max) || y_max <= 0) y_max <- max(y, na.rm = TRUE)
      y_max <- y_max * 1.15
      y_min <- 0

      shapes <- list()
      annots <- list()

      if (isTRUE(mf$ok)) {
        # Horizontale MFO-Linie
        shapes[[length(shapes) + 1]] <- list(
          type = "line", x0 = x_min, x1 = mf$Fatmax_W,
          y0 = mf$MFO, y1 = mf$MFO,
          line = list(color = "#ea580c", width = 1.5, dash = "dash"))
        # Vertikale Fatmax-Linie
        shapes[[length(shapes) + 1]] <- list(
          type = "line",
          x0 = mf$Fatmax_W, x1 = mf$Fatmax_W,
          y0 = y_min, y1 = mf$MFO,
          line = list(color = "#1d4ed8", width = 1.5, dash = "dash"))
        # MFO-Label
        annots[[length(annots) + 1]] <- list(
          x = x_min, y = mf$MFO, xanchor = "left", yanchor = "bottom",
          text = sprintf("<b>MFO = %.2f g·min⁻¹</b>", mf$MFO),
          showarrow = FALSE,
          font = list(color = "#9a3412", size = 12),
          bgcolor = "rgba(255,237,213,0.9)",
          bordercolor = "#fb923c", borderpad = 4)
        # Fatmax-Label
        annots[[length(annots) + 1]] <- list(
          x = mf$Fatmax_W, y = y_min, xanchor = "left", yanchor = "bottom",
          text = sprintf("<b>Fatmax = %.0f W</b>", mf$Fatmax_W),
          showarrow = FALSE,
          font = list(color = "#1e3a8a", size = 12),
          bgcolor = "rgba(219,234,254,0.9)",
          bordercolor = "#60a5fa", borderpad = 4,
          ax = 8, ay = 0)
      }

      # Funktionsgleichung + R² (oben rechts; feste Dezimalstellen je Term)
      if (is.finite(mf$coef_a %||% NA)) {
        sgn <- function(v) if (v >= 0) "+" else "−"
        eq_txt <- sprintf(
          "FO = %.6f·P² %s %.4f·P %s %.2f<br>R² = %.2f",
          mf$coef_a, sgn(mf$coef_b), abs(mf$coef_b),
          sgn(mf$coef_c), abs(mf$coef_c), mf$r2 %||% NA_real_)
        annots[[length(annots) + 1]] <- list(
          x = 0.99, y = 0.98, xref = "paper", yref = "paper",
          xanchor = "right", yanchor = "top",
          text = eq_txt, showarrow = FALSE, align = "right",
          font = list(color = "#475569", size = 11),
          bgcolor = "rgba(255,255,255,0.75)",
          bordercolor = "#cbd5e1", borderpad = 4)
      }

      # Build plot
      p <- plotly::plot_ly()

      # Polynomfit-Kurve (gestrichelt)
      if (length(fx) > 1) {
        p <- p |> plotly::add_lines(
          x = fx, y = fy,
          name = "Polynom 2. Grades",
          line = list(color = "#9ca3af", width = 1.6, dash = "dash"),
          hovertemplate = "P: %{x:.0f} W<br>FO (fit): %{y:.2f} g/min<extra></extra>")
      }

      # Datenpunkte (Quadrate, schwarz wie im Frontiers-Plot)
      p <- p |> plotly::add_markers(
        x = x, y = y,
        name = "Stufenwerte",
        marker = list(size = 9, color = "#0f172a",
          symbol = "square", line = list(color = "#fff", width = 1)),
        hovertemplate = "P: %{x:.0f} W<br>FO: %{y:.2f} g/min<extra></extra>")

      # MFO-Punkt highlighten
      if (isTRUE(mf$ok)) {
        p <- p |> plotly::add_markers(
          x = mf$Fatmax_W, y = mf$MFO,
          name = "MFO",
          marker = list(size = 13, color = "#f59e0b",
            symbol = "diamond", line = list(color = "#7c2d12", width = 2)),
          hovertemplate = sprintf(
            "<b>MFO = %.2f g/min</b><br>Fatmax = %.0f W<extra></extra>",
            mf$MFO, mf$Fatmax_W))
      }

      p |> plotly::layout(
        title = list(text = ""),
        xaxis = list(title = "Power [W]",
          range = c(x_min, x_max),
          zeroline = FALSE, gridcolor = "#e2e8f0", griddash = "dash"),
        yaxis = list(title = "Fettoxidation [g·min⁻¹]",
          range = c(y_min, y_max),
          zeroline = FALSE, gridcolor = "#e2e8f0", griddash = "dash"),
        shapes = shapes, annotations = annots,
        showlegend = TRUE,
        legend = list(orientation = "h", x = 0, y = 1.08,
          font = list(size = 10)),
        margin = list(t = 40, b = 50, l = 60, r = 20),
        paper_bgcolor = "#ffffff",
        plot_bgcolor  = "#fafbfc"
      ) |>
      plotly::config(displaylogo = FALSE)
    })

    # ── Tabelle ────────────────────────────────────────────
    output$steps_table_ui <- shiny::renderUI({
      df <- tryCatch(summary_r(), error = function(e) NULL)
      if (is.null(df) || nrow(df) == 0) {
        return(shiny::div(class = "steps-empty",
          shiny::icon("triangle-exclamation"),
          " Keine Stufen erkannt. ",
          "(Daten enthalten möglicherweise eine Rampe statt Stufen,",
          " oder die Mindestdauer ist zu hoch.)"))
      }

      fmt_min <- function(t) {
        if (!is.finite(t)) return("–")
        m <- floor(t); s <- round((t - m) * 60)
        sprintf("%02d:%02d", as.integer(m), as.integer(s))
      }
      fmt_n <- function(v, dp = 2) {
        if (!is.finite(v)) "–" else format(round(v, dp), nsmall = dp)
      }
      phase_pill <- function(type) {
        cls <- switch(type,
          "WarmUp" = "warmup",
          "Belastung" = "load",
          "Cooldown" = "cool",
          "")
        sprintf('<span class="phase-pill %s">%s</span>', cls, type)
      }
      row_class <- function(type) {
        switch(type,
          "WarmUp" = "row-warmup",
          "Belastung" = "row-load",
          "Cooldown" = "row-cool",
          "")
      }

      cols <- list(
        list("Nr",         "no",          0,    NULL),
        list("Bezeichnung","label",       NULL, NULL),
        list("Phase",      "type",        "ph", NULL),
        list("Start",      "t_start_min", "tt", NULL),
        list("Ende",       "t_end_min",   "tt", NULL),
        list("Dauer [s]",  "duration_sec",0,    NULL),
        list("P [W]",      "P",           0,    NULL),
        list("V'O₂ [L/min]", "VO2",  3,    NULL),
        list("V'O₂/kg [ml/min/kg]","VO2_kg", 1, "vo2kg"),
        list("V'CO₂ [L/min]","VCO2", 3,    NULL),
        list("V'E [L/min]","VE",          1,    NULL),
        list("HR [bpm]",   "HR",          0,    NULL),
        list("RER",        "RER",         2,    "rer"),
        list("FO [g/min]", "FO_g",        2,    "fo"),
        list("CHO [g/min]","CHO_g",       2,    "cho"),
        list("%FO",        "FO_pct",      1,    "fo_pct"),
        list("%CHO",       "CHO_pct",     1,    "cho_pct"),
        list("ET [kcal/min]","ET_kcal_min",2,   "et"),
        list("ET [kJ/min]","ET_kJ_min",   1,    "et")
      )

      header_html <- '<thead><tr>'
      for (c in cols) {
        cls <- if (!is.null(c[[4]])) ' class="col-clickable"' else ""
        att <- if (!is.null(c[[4]]))
          sprintf(' data-col="%s"', c[[4]]) else ""
        header_html <- paste0(header_html,
          "<th", cls, att, ">", c[[1]], "</th>")
      }
      header_html <- paste0(header_html, "</tr></thead>")

      body <- ""
      for (i in seq_len(nrow(df))) {
        r <- df[i, ]
        body <- paste0(body, '<tr class="', row_class(r$type), '">')
        for (c in cols) {
          key <- c[[2]]; dp <- c[[3]]
          v <- r[[key]]
          if (identical(dp, "ph")) {
            txt <- phase_pill(as.character(v))
          } else if (identical(dp, "tt")) {
            txt <- fmt_min(v)
          } else if (is.null(dp)) {
            txt <- if (is.na(v)) "–" else as.character(v)
          } else if (is.na(v)) {
            txt <- "–"
          } else if (dp == 0) {
            txt <- as.character(round(v))
          } else {
            txt <- fmt_n(v, dp)
          }
          if (key == "no" && is.na(v)) txt <- ""
          body <- paste0(body, "<td>", txt, "</td>")
        }
        body <- paste0(body, "</tr>")
      }
      shiny::HTML(paste0(
        '<div style="overflow-x:auto;">',
        '<table class="steps-table">',
        header_html,
        '<tbody>', body, '</tbody>',
        '</table></div>'))
    })

    # ── Formel-Modal bei Klick auf Spaltenkopf ──────────────
    shiny::observeEvent(input$show_formula, {
      col <- input$show_formula$col
      ftab <- formula_definitions()
      f <- ftab[[col]]
      if (is.null(f)) return()
      shiny::showModal(shiny::modalDialog(
        title = shiny::tagList(shiny::icon("function"), " ", f$title),
        shiny::withMathJax(
          shiny::div(class = "formula-modal-body",
            shiny::tags$p(f$desc),
            shiny::div(class = "formula-display",
              shiny::HTML(f$formula)),
            shiny::div(class = "ref",
              shiny::icon("book"), " ", f$ref))),
        easyClose = TRUE,
        size = "m",
        footer = shiny::modalButton("Schließen")))
    })

    # Erweiterte Einstellungen reactive für Export
    advanced_settings_r <- shiny::reactive({
      list(
        window_sec = input$window_sec,
        min_step   = input$min_step,
        weight     = input$weight
      )
    })

    return(list(
      summary           = summary_r,
      mfo               = mfo_r,
      advanced_settings = advanced_settings_r
    ))
  })
}


# ── Formel-Texte (MathJax) ───────────────────────────────────
formula_definitions <- function() {
  list(
    rer = list(
      title  = "RER (Respiratorischer Quotient)",
      desc   = "Verhältnis von CO₂-Abgabe zu O₂-Aufnahme.",
      formula = "$$ \\mathrm{RER} = \\frac{\\dot{V}\\mathrm{CO}_2}{\\dot{V}\\mathrm{O}_2} $$",
      ref    = "Standardgleichung; vgl. Wasserman et al., Principles of Exercise Testing."
    ),
    vo2kg = list(
      title  = "V'O₂ / kg (Sauerstoffaufnahme pro Körpergewicht)",
      desc   = "Sauerstoffaufnahme normiert auf das Körpergewicht.",
      formula = "$$ \\dot{V}\\mathrm{O}_{2}\\,/\\,\\mathrm{kg} \\; [\\mathrm{ml \\cdot min^{-1} \\cdot kg^{-1}}] = \\frac{\\dot{V}\\mathrm{O}_{2}\\,[\\mathrm{L \\cdot min^{-1}}] \\cdot 1000}{m\\,[\\mathrm{kg}]} $$",
      ref    = "Konvention: Umrechnung L → mL durch ×1000."
    ),
    fo = list(
      title  = "FO – Fettoxidation [g·min⁻¹]",
      desc   = "Fettoxidationsrate pro Minute aus Atemgasen.",
      formula = "$$ \\mathrm{FO}\\;[\\mathrm{g \\cdot min^{-1}}] = 1{,}695 \\cdot \\dot{V}\\mathrm{O}_2 - 1{,}701 \\cdot \\dot{V}\\mathrm{CO}_2 $$",
      ref    = "Achten J. & Jeukendrup A.E. (2003). Maximal fat oxidation during exercise in trained men. Int J Sports Med 24(8):603–608."
    ),
    cho = list(
      title  = "CHO – Kohlenhydratoxidation [g·min⁻¹]",
      desc   = "Kohlenhydratoxidationsrate pro Minute aus Atemgasen.",
      formula = "$$ \\mathrm{CHO}\\;[\\mathrm{g \\cdot min^{-1}}] = 4{,}585 \\cdot \\dot{V}\\mathrm{CO}_2 - 3{,}226 \\cdot \\dot{V}\\mathrm{O}_2 $$",
      ref    = "Achten J. & Jeukendrup A.E. (2003). Int J Sports Med 24(8):603–608."
    ),
    fo_pct = list(
      title  = "%FO – Anteil der Fettoxidation am Energieumsatz",
      desc   = "Prozentualer Energieanteil aus Fettoxidation, RER-basiert linear interpoliert (RER 0{,}707 = 100 % Fett, RER 1{,}000 = 0 % Fett).",
      formula = "$$ \\%\\mathrm{FO} = 1 - \\frac{\\mathrm{RER} - 0{,}707}{1{,}000 - 0{,}707} \\quad \\text{für } 0{,}707 \\leq \\mathrm{RER} \\leq 1 $$",
      ref    = "Péronnet F. & Massicotte D. (1991). Table of nonprotein respiratory quotient: an update. Can J Sport Sci 16(1):23–29."
    ),
    cho_pct = list(
      title  = "%CHO – Anteil der Kohlenhydratoxidation am Energieumsatz",
      desc   = "Prozentualer Energieanteil aus Kohlenhydraten, RER-basiert linear interpoliert.",
      formula = "$$ \\%\\mathrm{CHO} = \\frac{\\mathrm{RER} - 0{,}707}{1{,}000 - 0{,}707} \\quad \\text{für } 0{,}707 \\leq \\mathrm{RER} \\leq 1 $$",
      ref    = "Péronnet F. & Massicotte D. (1991). Can J Sport Sci 16(1):23–29."
    ),
    et = list(
      title  = "ET – Energy Turnover",
      desc   = "Energieumsatz pro Minute aus V'O₂ und Substrat-Anteilen.",
      formula = "$$ \\mathrm{ET}\\;[\\mathrm{kcal \\cdot min^{-1}}] = \\frac{\\dot{V}\\mathrm{O}_2 \\cdot \\left( \\%\\mathrm{FO} \\cdot 19{,}6 + \\%\\mathrm{CHO} \\cdot 21{,}1 \\right)}{4{,}18} $$",
      ref    = paste0(
        "Kroidl R., Schwarz S., Lehnigk B., Fritsch J. (2015). ",
        "Kursbuch Spiroergometrie, 3. Aufl., Thieme. ",
        "Kalorische Äquivalente: 19{,}6 kJ/L (Fett) bzw. 21{,}1 kJ/L (CHO).")
    )
  )
}

# ============================================================
#  mod_vt_analysis.R -- VT1/VT2 Analyse (v5)
#  Sidebar + VT-Seiten + Zwei-Segment-Regression + Hilfe
# ============================================================

mod_vt_ui <- function(id, vo2max_ui = NULL) {
  ns <- shiny::NS(id)

  # Ein Plot in der "Bühne": gross (is-main) oder klein (Vorschau).
  # Klick auf eine Vorschau tauscht sie nach oben (JS saStage).
  stage_item <- function(out_id, title, main = FALSE) {
    shiny::div(class = paste("vt-item", if (main) "is-main"),
      `data-title` = title,
      shiny::div(class = "vt-item-title", title),
      shiny::div(class = "vt-item-plot",
        plotly::plotlyOutput(ns(out_id), height = "100%")),
      shiny::tags$button(type = "button", class = "vt-item-pick",
        `aria-label` = paste(title, "gross anzeigen"),
        onclick = "saStage(this)"))
  }
  stage <- function(...) shiny::div(class = "card vt-stage", ...)

  # Inspektor fuer eine Schwelle (k = "vt1" / "vt2")
  inspector <- function(k, label) {
    shiny::tags$aside(class = "card vt-insp", `aria-label` = "Inspektor",
      shiny::div(class = "vt-sec",
        shiny::tags$h4("Ergebnis"),
        shiny::uiOutput(ns(paste0(k, "_status"))),
        shiny::uiOutput(ns(paste0(k, "_result"))),
        shiny::actionButton(ns(paste0(k, "_confirm")), paste(label, "bestätigen"),
          class = "btn-primary w-100", style = "margin-top:12px;"),
        shiny::actionButton(ns(paste0(k, "_reset")), "Auf Automatik zurücksetzen",
          icon = shiny::icon("rotate-left"),
          class = "btn-outline-secondary w-100", style = "margin-top:8px;")),
      shiny::div(class = "vt-sec",
        shiny::tags$h4("Zeitpunkt"),
        shiny::numericInput(ns(paste0(k, "_time")), label = NULL,
          value = NA, min = 0, max = 60, step = 0.05, width = "100%"),
        shiny::div(class = "vt-hint", "Minuten. Alternativ die Linie im Plot ziehen.")),
      shiny::div(class = "vt-sec",
        shiny::tags$h4("Kommentar"),
        shiny::textAreaInput(ns(paste0(k, "_comment")), label = NULL,
          value = "", width = "100%", rows = 3,
          placeholder = "Optional für den Bericht")))
  }

  # Gemeinsame Darstellungs-Einstellungen (einmalig, gilt fuer alle Plots)
  settings <- shiny::div(class = "card vt-settings",
    shiny::tags$h4("Darstellung"),
    shiny::div(class = "vt-settings-row",
      shiny::numericInput(ns("smooth"), "Glättung (Atemzüge)",
        value = 15, min = 3, max = 60, step = 1, width = "160px"),
      shiny::checkboxInput(ns("ph_warmup"), "Erwärmung", value = TRUE),
      shiny::checkboxInput(ns("ph_recovery"), "Erholung", value = FALSE)))

  shiny::tagList(
    shiny::tags$style(shiny::HTML("
      .vt-layout { display:grid; grid-template-columns:minmax(0,1fr) 280px; gap:12px; align-items:start; }
      @media (max-width:1100px) { .vt-layout { grid-template-columns:minmax(0,1fr); } }
      .vt-stage { padding:12px; display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; }
      .vt-item { position:relative; border:1px solid var(--sa-sep-soft); border-radius:var(--sa-radius-sm); padding:6px 6px 4px; min-width:0; }
      .vt-item-title { font-size:0.8125rem; font-weight:500; padding:0 2px 4px; }
      .vt-item-plot { height:170px; }
      .vt-item-pick { position:absolute; inset:0; background:transparent; border:0; cursor:pointer; border-radius:inherit; }
      .vt-item-pick:hover { background:rgba(0,0,0,.025); }
      .vt-item.is-main { grid-column:1 / -1; order:-1; border:0; padding:0; }
      .vt-item.is-main .vt-item-title { font-size:0.9375rem; font-weight:600; padding:2px 2px 6px; }
      .vt-item.is-main .vt-item-plot { height:440px; }
      .vt-item.is-main .vt-item-pick { display:none; }
      .vt-insp { padding:0; }
      .vt-sec { padding:14px 16px; border-top:1px solid var(--sa-sep-soft); }
      .vt-sec:first-child { border-top:0; }
      .vt-sec h4 { margin:0 0 8px; font-size:0.6875rem; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--sa-text-2); }
      .vt-sec .form-group { margin-bottom:0; }
      .vt-hint { margin-top:6px; color:var(--sa-text-2); font-size:0.75rem; }
      .vt-status { display:inline-flex; align-items:center; gap:6px; font-size:0.75rem; margin-bottom:4px; }
      .vt-status .dot { width:7px; height:7px; border-radius:50%; background:currentColor; }
      .vt-status.open { color:#8a5a00; } .vt-status.open .dot { background:transparent; border:1.5px solid currentColor; }
      .vt-status.ok { color:#1f7a3a; }
      .vt-big { font-size:1.75rem; font-weight:600; letter-spacing:-.02em; font-variant-numeric:tabular-nums; }
      .vt-big small { font-size:0.875rem; color:var(--sa-text-2); font-weight:500; margin-left:3px; }
      .vt-mini { display:grid; grid-template-columns:1fr auto; row-gap:4px; margin-top:8px; font-variant-numeric:tabular-nums; }
      .vt-mini span:nth-child(odd) { color:var(--sa-text-2); }
      .vt-mini span:nth-child(even) { font-weight:600; text-align:right; }
      .vt-settings { padding:12px 16px; margin-top:12px; }
      .vt-settings h4 { margin:0 0 6px; font-size:0.6875rem; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--sa-text-2); }
      .vt-settings-row { display:flex; align-items:flex-end; gap:20px; flex-wrap:wrap; }
      .vt-settings-row .form-group, .vt-settings-row .checkbox { margin-bottom:0; }
      .vt-param-tbl { width:100%; border-collapse:collapse; font-size:0.875rem; font-variant-numeric:tabular-nums; }
      .vt-param-tbl th { padding:6px 8px; font-weight:600; text-align:right; color:var(--sa-text-2); border-bottom:1px solid var(--sa-sep); }
      .vt-param-tbl th.vt1-h { color:var(--sa-vt1); } .vt-param-tbl th.vt2-h { color:var(--sa-vt2); }
      .vt-param-tbl td { padding:6px 8px; text-align:right; border-bottom:1px solid var(--sa-sep-soft); }
      .vt-param-tbl td:first-child, .vt-param-tbl th:first-child { text-align:left; color:var(--sa-text-2); }
      .vt-param-tbl tr:last-child td { border-bottom:0; }
    ")),
    shiny::tags$script(shiny::HTML("
      function saStage(btn) {
        var item = btn.closest('.vt-item'), stage = item.parentElement;
        var main = stage.querySelector('.vt-item.is-main');
        if (main) main.classList.remove('is-main');
        item.classList.add('is-main');
        stage.querySelectorAll('.js-plotly-plot').forEach(function(el) {
          if (window.Plotly) Plotly.Plots.resize(el);
        });
      }
      // Plots in versteckten Seiten haben Breite 0 -> beim Einblenden neu messen
      $(document).on('shown.bs.tab', function() {
        setTimeout(function() {
          document.querySelectorAll('.vt-stage .js-plotly-plot').forEach(function(el) {
            if (el.offsetWidth && window.Plotly) Plotly.Plots.resize(el);
          });
        }, 30);
      });
    ")),

    bslib::navset_hidden(id = ns("page"),
      bslib::nav_panel_hidden("vt1",
        shiny::div(class = "vt-layout",
          shiny::div(
            stage(
              stage_item("p_vslope",  "V-Slope (V'CO₂ gegen V'O₂)", main = TRUE),
              stage_item("p_eq_vt1",  "Atemäquivalente"),
              stage_item("p_pet_vt1", "PetO₂ / PetCO₂"),
              stage_item("p_exco2",   "Excess CO₂")),
            settings),
          inspector("vt1", "VT1"))),

      bslib::nav_panel_hidden("vt2",
        shiny::div(class = "vt-layout",
          shiny::div(
            stage(
              stage_item("p_ve_vco2", "V'E gegen V'CO₂", main = TRUE),
              stage_item("p_eq_vt2",  "Atemäquivalente"),
              stage_item("p_pet_vt2", "PetO₂ / PetCO₂"),
              stage_item("p_exve",    "Excess V'E"))),
          inspector("vt2", "VT2"))),

      bslib::nav_panel_hidden("vo2max",
        if (!is.null(vo2max_ui)) vo2max_ui),

      bslib::nav_panel_hidden("vtsum",
        shiny::div(class = "vt-layout",
          shiny::div(
            shiny::div(class = "card", style = "padding:12px;",
              shiny::div(class = "vt-item-title", "V'O₂ und V'CO₂ im Zeitverlauf"),
              plotly::plotlyOutput(ns("p_overview"), height = "380px")),
            shiny::div(class = "card", style = "padding:12px; margin-top:12px;",
              shiny::div(class = "vt-item-title", "RER"),
              plotly::plotlyOutput(ns("p_rer"), height = "300px"))),
          shiny::tags$aside(class = "card vt-insp",
            shiny::div(class = "vt-sec",
              shiny::tags$h4("Werte an den Schwellen"),
              shiny::uiOutput(ns("vt_params")),
              shiny::div(class = "vt-hint", "Mittel über ±15 s.")),
            shiny::div(class = "vt-sec",
              shiny::tags$h4("Allgemeiner Kommentar"),
              shiny::textAreaInput(ns("general_comment"), label = NULL,
                value = "", width = "100%", rows = 4,
                placeholder = "Allgemeine Hinweise zur Spiroergometrie")))))
    )
  )
}


# ============================================================
#  SERVER
# ============================================================
mod_vt_server <- function(id, params_reactive) {
  shiny::moduleServer(id, function(input, output, session) {
    ns <- session$ns

    # ── State ───────────────────────────────────────────────────
    vt <- shiny::reactiveValues(
      vt1_time = NA_real_, vt2_time = NA_real_,
      vt1_final = NA_real_, vt2_final = NA_real_,
      vt1_method = "auto", vt2_method = "auto",
      vt1_confirmed = FALSE, vt2_confirmed = FALSE,
      slope1_offset = 0,
      # Kommentare (kontextuell zu VT1/VT2 + allgemeiner Spiro-Kommentar)
      vt1_comment = "", vt2_comment = "", general_comment = ""
    )

    # ── Gefilterte Zeitreihe ────────────────────────────────────
    ts_r <- shiny::reactive({
      p <- params_reactive(); shiny::req(p, !is.null(p$ts))
      ts <- p$ts
      keep <- c("Belastung", "Exercise")
      if (isTRUE(input$ph_warmup))
        keep <- c(keep, "Warmup", "Warm Up", "Warm-Up",
                  "Erwärmung", "Erwaermung")
      if (isTRUE(input$ph_recovery))
        keep <- c(keep, "Cooldown", "Cool Down", "Erholung", "Recovery")
      ts |>
        dplyr::filter(Phase %in% keep | is.na(Phase)) |>
        dplyr::arrange(time_min)
    })

    sn <- shiny::reactive(input$smooth %||% 15)

    # ── Init ────────────────────────────────────────────────────
    shiny::observeEvent(params_reactive(), {
      p <- params_reactive(); shiny::req(p, !is.null(p$ts))
      t1 <- if (is.finite(p$vt1_time %||% NA)) p$vt1_time else {
        idx <- tryCatch(auto_vt1(p$ts), error = function(e) NA_integer_)
        vt_idx_to_time(p$ts, idx)
      }
      t2 <- if (is.finite(p$vt2_time %||% NA)) p$vt2_time else {
        idx <- tryCatch(auto_vt2(p$ts), error = function(e) NA_integer_)
        vt_idx_to_time(p$ts, idx)
      }
      vt$vt1_time <- t1; vt$vt2_time <- t2
      vt$vt1_final <- NA_real_; vt$vt2_final <- NA_real_
      vt$vt1_method <- if (is.finite(p$vt1_time %||% NA)) "Excel" else "auto"
      vt$vt2_method <- if (is.finite(p$vt2_time %||% NA)) "Excel" else "auto"
      vt$vt1_confirmed <- FALSE; vt$vt2_confirmed <- FALSE
      # Kommentare bei Datei-Wechsel zuruecksetzen (messungsspezifisch)
      vt$vt1_comment <- ""; vt$vt2_comment <- ""; vt$general_comment <- ""
      shiny::updateTextAreaInput(session, "vt1_comment", value = "")
      shiny::updateTextAreaInput(session, "vt2_comment", value = "")
      shiny::updateTextAreaInput(session, "general_comment", value = "")
      shiny::updateNumericInput(session, "vt1_time",
        value = if (is.finite(t1)) round(t1, 2) else NA)
      shiny::updateNumericInput(session, "vt2_time",
        value = if (is.finite(t2)) round(t2, 2) else NA)
    })

    # Kommentar-Felder mit reactiveValues synchronisieren
    shiny::observeEvent(input$vt1_comment, {
      vt$vt1_comment <- input$vt1_comment %||% ""
    }, ignoreNULL = FALSE)
    shiny::observeEvent(input$vt2_comment, {
      vt$vt2_comment <- input$vt2_comment %||% ""
    }, ignoreNULL = FALSE)
    shiny::observeEvent(input$general_comment, {
      vt$general_comment <- input$general_comment %||% ""
    }, ignoreNULL = FALSE)

    # ── JS Drag → VT Update ────────────────────────────────────
    shiny::observeEvent(input$drag_vt1, {
      t <- input$drag_vt1$time
      if (is.finite(t)) {
        vt$vt1_time <- t
        vt$vt1_method <- "manuell"; vt$vt1_confirmed <- FALSE
        shiny::updateNumericInput(session, "vt1_time", value = round(t, 2))
      }
    })
    shiny::observeEvent(input$drag_vt2, {
      t <- input$drag_vt2$time
      if (is.finite(t)) {
        vt$vt2_time <- t
        vt$vt2_method <- "manuell"; vt$vt2_confirmed <- FALSE
        shiny::updateNumericInput(session, "vt2_time", value = round(t, 2))
      }
    })
    # V'E~V'CO2-Plot: x-Achse ist V'CO2, nicht Zeit. Gezogene VT2-Linie
    # liefert einen V'CO2-Wert → auf nächstgelegene Belastungs-Zeit mappen.
    shiny::observeEvent(input$drag_vt2_vco2, {
      v <- input$drag_vt2_vco2$vco2
      if (is.null(v) || !is.finite(v)) return()
      d <- tryCatch(ts_r(), error = function(e) NULL)
      if (is.null(d) || nrow(d) < 5) return()
      d$VCO2_s <- safe_roll(d$VCO2, sn())
      bel <- d[d$Phase %in% c("Belastung", "Exercise") &
                 is.finite(d$VCO2_s), , drop = FALSE]
      if (nrow(bel) == 0) bel <- d[is.finite(d$VCO2_s), , drop = FALSE]
      if (nrow(bel) == 0) return()
      t <- bel$time_min[which.min(abs(bel$VCO2_s - v))]
      if (is.finite(t)) {
        vt$vt2_time <- t
        vt$vt2_method <- "manuell"; vt$vt2_confirmed <- FALSE
        shiny::updateNumericInput(session, "vt2_time", value = round(t, 2))
      }
    })

    # ── NumericInput → VT ───────────────────────────────────────
    shiny::observeEvent(input$vt1_time, {
      if (!is.finite(input$vt1_time)) return()
      vt$vt1_time <- input$vt1_time
      vt$vt1_method <- "manuell"; vt$vt1_confirmed <- FALSE
    }, ignoreInit = TRUE)
    shiny::observeEvent(input$vt2_time, {
      if (!is.finite(input$vt2_time)) return()
      vt$vt2_time <- input$vt2_time
      vt$vt2_method <- "manuell"; vt$vt2_confirmed <- FALSE
    }, ignoreInit = TRUE)

    # ── Reset ───────────────────────────────────────────────────
    shiny::observeEvent(input$vt1_reset, {
      p <- tryCatch(params_reactive(), error = function(e) NULL)
      if (is.null(p)) return()
      t1 <- if (is.finite(p$vt1_time %||% NA)) p$vt1_time
            else vt_idx_to_time(p$ts,
                   tryCatch(auto_vt1(p$ts), error = function(e) NA_integer_))
      vt$vt1_time <- t1; vt$vt1_method <- "auto"; vt$vt1_confirmed <- FALSE
      shiny::updateNumericInput(session, "vt1_time",
        value = if (is.finite(t1)) round(t1, 2) else NA)
    })
    shiny::observeEvent(input$vt2_reset, {
      p <- tryCatch(params_reactive(), error = function(e) NULL)
      if (is.null(p)) return()
      t2 <- if (is.finite(p$vt2_time %||% NA)) p$vt2_time
            else vt_idx_to_time(p$ts,
                   tryCatch(auto_vt2(p$ts), error = function(e) NA_integer_))
      vt$vt2_time <- t2; vt$vt2_method <- "auto"; vt$vt2_confirmed <- FALSE
      shiny::updateNumericInput(session, "vt2_time",
        value = if (is.finite(t2)) round(t2, 2) else NA)
    })

    # ── S=1-Linie verschoben (Slope bleibt 1, nur Offset ändert sich) ──
    shiny::observeEvent(input$drag_slope1, {
      off <- input$drag_slope1$offset
      if (is.finite(off)) vt$slope1_offset <- off
    })

    # ── Bestätigen (unter den Plots) ────────────────────────────
    shiny::observeEvent(input$vt1_confirm, {
      vt$vt1_final <- vt$vt1_time; vt$vt1_confirmed <- TRUE
      shiny::showNotification("VT1 bestätigt", type = "message", duration = 2)
    })
    shiny::observeEvent(input$vt2_confirm, {
      vt$vt2_final <- vt$vt2_time; vt$vt2_confirmed <- TRUE
      shiny::showNotification("VT2 bestätigt", type = "message", duration = 2)
    })

    # ── Status-Anzeige ──────────────────────────────────────────
    status_ui <- function(k) {
      conf <- vt[[paste0(k, "_confirmed")]]; meth <- vt[[paste0(k, "_method")]]
      src <- switch(meth, Excel = "Gerätedatei", auto = "Automatik",
                    manuell = "manuell gesetzt", meth)
      shiny::div(class = paste("vt-status", if (conf) "ok" else "open"),
        shiny::span(class = "dot"),
        if (conf) paste0("Bestätigt, Quelle: ", src)
        else paste0("Nicht bestätigt, Quelle: ", src))
    }
    output$vt1_status <- shiny::renderUI(status_ui("vt1"))
    output$vt2_status <- shiny::renderUI(status_ui("vt2"))

    result_ui <- function(tv) {
      ts <- tryCatch(ts_r(), error = function(e) NULL)
      if (is.null(ts) || !is.finite(tv))
        return(shiny::div(class = "vt-big", "–"))
      f <- function(col, d) {
        v <- vt_mean_at(ts, col, tv)
        if (is.finite(v)) format(round(v, d), nsmall = d, decimal.mark = ",") else "–"
      }
      p <- interp_vt_power(ts, tv)
      shiny::tagList(
        shiny::div(class = "vt-big",
          format(round(tv, 2), nsmall = 2, decimal.mark = ","), shiny::tags$small("min")),
        shiny::div(class = "vt-mini",
          shiny::span("Leistung"), shiny::span(if (is.finite(p)) paste(round(p), "W") else "–"),
          shiny::span("V'O₂"), shiny::span(paste(f("VO2abs", 2), "L/min")),
          shiny::span("HF"), shiny::span(paste(f("HR", 0), "/min")),
          shiny::span("RER"), shiny::span(f("RER", 2))),
        shiny::div(class = "vt-hint", "Werte als Mittel über ±15 s."))
    }
    output$vt1_result <- shiny::renderUI(result_ui(vt$vt1_time))
    output$vt2_result <- shiny::renderUI(result_ui(vt$vt2_time))

    # Unterseite wird von aussen (Seitenleiste) gesetzt
    shiny::observeEvent(input$sub, {
      bslib::nav_select("page", input$sub)
    })

    # ══════════════════════════════════════════════════════════════
    #  VT-PARAMETER (Wide HTML-Tabelle)
    # ══════════════════════════════════════════════════════════════
    output$vt_params <- shiny::renderUI({
      ts <- tryCatch(ts_r(), error = function(e) NULL)
      if (is.null(ts) || nrow(ts) < 5)
        return(shiny::div(style = "color:#94a3b8;", "Keine Daten"))
      t1 <- vt$vt1_time; t2 <- vt$vt2_time
      val_at <- function(col, tv) {
        if (!is.finite(tv) || !col %in% names(ts)) return("-")
        v <- vt_mean_at(ts, col, tv)
        if (!is.finite(v)) return("-")
        if (col %in% c("VO2abs","VCO2")) format(round(v,3), nsmall=3)
        else if (col %in% c("VE","HR","P")) as.character(round(v,0))
        else if (col == "RER") format(round(v,2), nsmall=2)
        else format(round(v,1), nsmall=1)
      }
      fmt_t <- function(tv) if (is.finite(tv)) format(round(tv,2), nsmall=2) else "-"
      # Leistung zwischen Stufen linear interpoliert (ganze Zahl)
      pw_at <- function(tv) {
        v <- interp_vt_power(ts, tv)
        if (is.finite(v)) as.character(round(v, 0)) else "-"
      }
      rows <- list(
        c("Zeit (min)",        fmt_t(t1),             fmt_t(t2)),
        c("Leistung (W)",      pw_at(t1),             pw_at(t2)),
        c("VO\u2082 (L/min)",  val_at("VO2abs",t1),   val_at("VO2abs",t2)),
        c("VCO\u2082 (L/min)", val_at("VCO2",t1),     val_at("VCO2",t2)),
        c("VE (L/min)",        val_at("VE",t1),       val_at("VE",t2)),
        c("HR (bpm)",          val_at("HR",t1),       val_at("HR",t2)),
        c("RER",               val_at("RER",t1),      val_at("RER",t2)),
        c("VE/VO\u2082",       val_at("VE_VO2",t1),   val_at("VE_VO2",t2)),
        c("VE/VCO\u2082",      val_at("VE_VCO2",t1),  val_at("VE_VCO2",t2)),
        c("Methode",           vt$vt1_method,          vt$vt2_method),
        c("Status",
          if (vt$vt1_confirmed) "Final" else "\u2013",
          if (vt$vt2_confirmed) "Final" else "\u2013"))
      html <- paste0(
        '<table class="vt-param-tbl"><thead><tr>',
        '<th></th><th class="vt1-h">VT1</th><th class="vt2-h">VT2</th>',
        '</tr></thead><tbody>')
      for (r in rows)
        html <- paste0(html,'<tr><td>',r[1],'</td><td>',r[2],'</td><td>',r[3],'</td></tr>')
      shiny::HTML(paste0(html, '</tbody></table>'))
    })

    # ══════════════════════════════════════════════════════════════
    #  PLOT HELPERS
    # ══════════════════════════════════════════════════════════════

    # ── Phasen-Hintergründe (NICHT verschiebbar, gelb/blau/lila) ──
    phase_shapes <- function(d) {
      shapes <- list()
      if (is.null(d) || nrow(d) == 0 || !"Phase" %in% names(d)) return(shapes)
      cols <- list(
        "Erwärmung" = "rgba(252,211,77,0.22)",   # warmes Gelb
        "Erwaermung"= "rgba(252,211,77,0.22)",
        "Belastung" = "rgba(147,197,253,0.22)",  # Sky-Blue
        "Exercise"  = "rgba(147,197,253,0.22)",
        "Erholung"  = "rgba(216,180,254,0.28)",  # Lavendel
        "Recovery"  = "rgba(216,180,254,0.28)"
      )
      ph <- as.character(d$Phase); ph[is.na(ph)] <- ""
      r  <- rle(ph)
      ends   <- cumsum(r$lengths)
      starts <- c(1, head(ends, -1) + 1)
      for (i in seq_along(r$values)) {
        p <- r$values[i]
        if (p %in% names(cols)) {
          x0 <- d$time_min[starts[i]]
          x1 <- d$time_min[ends[i]]
          if (is.finite(x0) && is.finite(x1) && x1 > x0) {
            shapes[[length(shapes)+1]] <- list(
              type="rect", x0=x0, x1=x1, y0=0, y1=1, yref="paper",
              fillcolor=cols[[p]], line=list(width=0),
              layer="below", editable=FALSE)
          }
        }
      }
      shapes
    }

    # ── VT-Marker-Linie (verschiebbar) ──
    vt_marker_shape <- function(t, color) {
      if (!is.finite(t)) return(list())
      list(list(
        type="line", x0=t, x1=t, y0=0, y1=1, yref="paper",
        line=list(color=color, width=2.5),
        layer="above", editable=TRUE))
    }

    # ── Schöne MM:SS-Zeitachse ──
    pretty_time_axis <- function(d) {
      tmax <- if (is.null(d) || nrow(d) == 0) 20 else max(d$time_min, na.rm = TRUE)
      if (!is.finite(tmax) || tmax <= 0) tmax <- 20
      step <- if (tmax <= 8) 1 else if (tmax <= 20) 2 else if (tmax <= 40) 4 else 5
      vals <- seq(0, ceiling(tmax/step) * step, by = step)
      txt  <- sprintf("%02d:%02d",
        as.integer(vals),
        as.integer(round((vals - as.integer(vals)) * 60)))
      list(
        title = list(text = "Zeit", font = list(size = 11)),
        tickmode = "array", tickvals = vals, ticktext = txt,
        showgrid = TRUE, gridcolor = "#e2e8f0", griddash = "dash",
        zeroline = FALSE, ticks = "outside", tickfont = list(size = 10))
    }

    # ── Pro-Tab Shape-Listen ──
    # WICHTIG: VT-Linie zuerst (Index 0), Phasen danach – damit der
    # Drag-Handler immer shape[0] = VT-Linie sieht.
    vt1_shapes <- shiny::reactive({
      ts <- tryCatch(ts_r(), error = function(e) NULL)
      c(vt_marker_shape(vt$vt1_time, "#006400"),
        phase_shapes(ts))
    })
    vt2_shapes <- shiny::reactive({
      ts <- tryCatch(ts_r(), error = function(e) NULL)
      c(vt_marker_shape(vt$vt2_time, "#6B8E23"),
        phase_shapes(ts))
    })
    # Übersicht: VT1 = shape[0], VT2 = shape[1], Phasen danach
    vt_shapes <- shiny::reactive({
      ts <- tryCatch(ts_r(), error = function(e) NULL)
      c(vt_marker_shape(vt$vt1_time, "#006400"),
        vt_marker_shape(vt$vt2_time, "#6B8E23"),
        phase_shapes(ts))
    })

    # JS für VT1-Tabs: nur shape[0] → drag_vt1
    drag_js_vt1 <- sprintf("
      function(el, x) {
        el.on('plotly_relayout', function(ed) {
          if (!ed) return;
          var v = ed['shapes[0].x0'];
          if (v !== undefined && isFinite(v))
            Shiny.setInputValue('%s', {time:v, nonce:Math.random()},
              {priority:'event'});
        });
      }
    ", ns("drag_vt1"))

    # JS für VT2-Tabs: nur shape[0] → drag_vt2
    drag_js_vt2 <- sprintf("
      function(el, x) {
        el.on('plotly_relayout', function(ed) {
          if (!ed) return;
          var v = ed['shapes[0].x0'];
          if (v !== undefined && isFinite(v))
            Shiny.setInputValue('%s', {time:v, nonce:Math.random()},
              {priority:'event'});
        });
      }
    ", ns("drag_vt2"))

    # JS für Übersicht: shape[0] → vt1, shape[1] → vt2
    drag_js_both <- sprintf("
      function(el, x) {
        el.on('plotly_relayout', function(ed) {
          if (!ed) return;
          var keys = Object.keys(ed);
          for (var i = 0; i < keys.length; i++) {
            if (keys[i].indexOf('shapes[0].x0') >= 0 && isFinite(ed[keys[i]]))
              Shiny.setInputValue('%s', {time:ed[keys[i]], nonce:Math.random()},
                {priority:'event'});
            if (keys[i].indexOf('shapes[1].x0') >= 0 && isFinite(ed[keys[i]]))
              Shiny.setInputValue('%s', {time:ed[keys[i]], nonce:Math.random()},
                {priority:'event'});
          }
        });
      }
    ", ns("drag_vt1"), ns("drag_vt2"))

    # JS für V'E~V'CO2: shape[0] (VT2-Linie) → V'CO2-Wert an drag_vt2_vco2
    drag_js_vt2_vco2 <- sprintf("
      function(el, x) {
        el.on('plotly_relayout', function(ed) {
          if (!ed) return;
          var v = ed['shapes[0].x0'];
          if (v !== undefined && isFinite(v))
            Shiny.setInputValue('%s', {vco2:v, nonce:Math.random()},
              {priority:'event'});
        });
      }
    ", ns("drag_vt2_vco2"))

    # Edit-Optionen: NUR Shape-Positionen ändern, keine Titel/Achsen/Legende
    drag_edits <- list(
      shapePosition = TRUE,
      titleText = FALSE,
      axisTitleText = FALSE,
      legendPosition = FALSE,
      annotationPosition = FALSE,
      annotationText = FALSE,
      annotationTail = FALSE)

    add_drag_vt1 <- function(p) {
      p |>
        plotly::config(editable = TRUE, edits = drag_edits,
          displaylogo = FALSE) |>
        htmlwidgets::onRender(drag_js_vt1)
    }
    add_drag_vt2 <- function(p) {
      p |>
        plotly::config(editable = TRUE, edits = drag_edits,
          displaylogo = FALSE) |>
        htmlwidgets::onRender(drag_js_vt2)
    }
    add_drag_vt2_vco2 <- function(p) {
      p |>
        plotly::config(editable = TRUE, edits = drag_edits,
          displaylogo = FALSE) |>
        htmlwidgets::onRender(drag_js_vt2_vco2)
    }
    add_drag <- function(p) {
      p |>
        plotly::config(editable = TRUE, edits = drag_edits,
          displaylogo = FALSE) |>
        htmlwidgets::onRender(drag_js_both)
    }

    m <- list(t=30, b=40, l=55, r=20)
    m_dual <- list(t=30, b=40, l=55, r=55)

    # Helper: 2-Segment-Regression als Shapes (grau, dünn, gestrichelt,
    # layer="below" → hinter den Punkten, ganzer Chart)
    two_seg_shapes <- function(x_vec, y_vec, x_min, x_max, min_seg = 10) {
      out <- list(shapes = list(), s1 = NA_real_, s2 = NA_real_)
      ok <- is.finite(x_vec) & is.finite(y_vec)
      if (sum(ok) < 2 * min_seg) return(out)
      bp <- tryCatch(
        find_breakpoint(x_vec, y_vec, min_seg = min_seg),
        error = function(e) NA_integer_)
      if (is.na(bp)) return(out)
      idx_ok <- which(ok); bp_pos <- match(bp, idx_ok)
      if (is.na(bp_pos) || bp_pos < min_seg) return(out)
      n <- length(idx_ok)
      s1_idx <- idx_ok[1:bp_pos]
      s2_idx <- idx_ok[(bp_pos+1):n]
      fit1 <- tryCatch(lm(y_vec[s1_idx] ~ x_vec[s1_idx]),
        error = function(e) NULL)
      fit2 <- tryCatch(lm(y_vec[s2_idx] ~ x_vec[s2_idx]),
        error = function(e) NULL)
      if (is.null(fit1) || is.null(fit2)) return(out)
      a1 <- as.numeric(coef(fit1)[1]); b1 <- as.numeric(coef(fit1)[2])
      a2 <- as.numeric(coef(fit2)[1]); b2 <- as.numeric(coef(fit2)[2])
      grey <- "#9ca3af"
      out$shapes <- list(
        list(type = "line",
          x0 = x_min, y0 = a1 + b1 * x_min,
          x1 = x_max, y1 = a1 + b1 * x_max,
          line = list(color = grey, width = 1.2, dash = "dash"),
          layer = "below", editable = FALSE),
        list(type = "line",
          x0 = x_min, y0 = a2 + b2 * x_min,
          x1 = x_max, y1 = a2 + b2 * x_max,
          line = list(color = grey, width = 1.2, dash = "dot"),
          layer = "below", editable = FALSE))
      out$s1 <- b1; out$s2 <- b2
      out
    }

